X = check_array(X, dtype=FLOAT_DTYPES, accept_sparse='csc')
n_samples, n_features = X.shape

if n_features != self.n_input_features_:
    raise ValueError("X shape does not match training shape")

combinations = self._combinations(n_features, self.degree,
                                  self.interaction_only,
                                  self.include_bias)
if sparse.isspmatrix(X):
    columns = []
    for c in combinations:
        if not c:
            column = sparse.csc_matrix(np.ones((n_samples, 1),
                                               dtype=X.dtype))
        else:
            column = X[:, c[0]]
            for j in c[1:]:
                column = column.multiply(X[:, j])
        columns.append(column)
    if columns:
        XP = sparse.hstack(columns, format='csc')
    else:
        XP = sparse.csc_matrix((n_samples, 0), dtype=X.dtype)
else:
    XP = np.empty((n_samples, self.n_output_features_), dtype=X.dtype)
    for i, c in enumerate(combinations):
        XP[:, i] = X[:, c].prod(1)

return XP
